import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, smoothstep, mul } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root object
  const root = new Group();

  // ---------- Background Plane with edge fade ----------
  const bgGeom = new PlaneGeometry(7.0, 0.35);
  const baseColorNode = color('#111117');
  const uvNode = uv();

  // left fade (0 → 0.09) and right fade (0.91 → 1)
  const leftFade = smoothstep(0.0, 0.09, uvNode.x);
  const rightFade = smoothstep(0.91, 1.0, uvNode.x);
  const alphaNode = mul(leftFade, rightFade);

  const bgMat = new MeshBasicNodeMaterial({
    transparent: true,
    colorNode: baseColorNode,
    alphaNode: alphaNode,
    side: ctx.THREE.DoubleSide,
  });

  const bgMesh = new Mesh(bgGeom, bgMat);
  root.add(bgMesh);

  // ---------- Top & Bottom hairlines ----------
  const lineHeight = 0.006;
  const lineWidth = 7.0;
  const lineColor = new Color('#23232b');
  const lineGeom = new PlaneGeometry(lineWidth, lineHeight);
  const lineMat = new MeshBasicNodeMaterial({ color: lineColor });

  const topLine = new Mesh(lineGeom, lineMat);
  topLine.position.set(0, 0.35 / 2 - lineHeight / 2, 0.001);
  root.add(topLine);

  const bottomLine = new Mesh(lineGeom, lineMat);
  bottomLine.position.set(0, -0.35 / 2 + lineHeight / 2, 0.001);
  root.add(bottomLine);

  // ---------- Ticker Content ----------
  const items = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const tickerContainer = new Group();
  const tickWidth = 0.02;
  const tickHeight = 0.14;
  const gapUnits = 0.5; // 2 × base unit (0.25)

  // Approximate character width based on fontSize
  const approxCharWidth = 0.13;

  // Tick material (emissive)
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    metalness: 0.0,
    roughness: 0.5,
  });

  let cursor = 0;

  items.forEach((item, idx) => {
    // Text
    const txt = ctx.fontAtlas.createText(item, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 13 * 0.06,
    });
    // Approximate width
    const textWidth = (item.length || 1) * approxCharWidth;
    txt.position.set(cursor + textWidth / 2, 0, 0.02);
    tickerContainer.add(txt);
    cursor += textWidth + gapUnits;

    // Tick (except after last item)
    if (idx < items.length - 1) {
      const tickGeom = new PlaneGeometry(tickWidth, tickHeight);
      const tick = new Mesh(tickGeom, tickMat);
      tick.position.set(cursor + tickWidth / 2, 0, 0.02);
      tickerContainer.add(tick);
      cursor += tickWidth + gapUnits;
    }
  });

  const segmentLength = cursor; // total length of one strip

  // Duplicate for seamless looping
  const tickerClone = tickerContainer.clone(true);
  tickerClone.position.x = segmentLength;
  const tickerGroup = new Group();
  tickerGroup.add(tickerContainer);
  tickerGroup.add(tickerClone);
  root.add(tickerGroup);

  // ---------- Scrolling Animation ----------
  const scrollDuration = segmentLength / 0.4; // speed = 0.4 units/sec
  const scrollTimeline = gsap.timeline({ repeat: -1, defaults: { ease: 'none' } });
  scrollTimeline.to(tickerGroup.position, {
    x: -segmentLength,
    duration: scrollDuration,
  });

  // ---------- Cinematic Primitive ----------
  const primitiveEntries = config.cinematicPrimitives ?? [];
  const primitiveRefs = [];

  primitiveEntries.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const ref = ctx.primitives[prim.name](tickerGroup, prim.params);
      primitiveRefs.push(ref);
    }
  });

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    bgGeom.dispose();
    bgMat.dispose();
    lineGeom.dispose();
    lineMat.dispose();
    tickMat.dispose();
    tickerGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry.dispose();
        if (obj.material && obj.material.dispose) obj.material.dispose();
      }
    });
    // Kill GSAP timelines
    scrollTimeline.kill();
    // Primitive cleanups
    primitiveRefs.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
  };

  return root;
}
